def material_text(p):
    i=p.get('item',p); key=i.get('intended_key',''); return ' '.join([i.get('tested_construct',''),i.get('lead_in',''),i.get('options',{}).get(key,'')]).casefold()
def has_anchor(text,a):
    if re.fullmatch(r'[a-z0-9_.+-]+',a): return re.search(r'(?<![a-z0-9])'+re.escape(a)+r'(?![a-z0-9])',text) is not None
    return a in text

def validate(items):
    if [x['num'] for x in items]!=list(range(1281,1291)):raise SystemExit('range')
    seq=''.join(x['item']['intended_key'] for x in items)
    if seq!='BDACECAEDB' or Counter(seq)!=Counter({'A':2,'B':2,'C':2,'D':2,'E':2}):raise SystemExit('keys')
    if Counter(x['blueprint']['primary_system'] for x in items)!=Counter({ENDO:5,RENAL:5}):raise SystemExit('systems')
    if Counter(x['blueprint']['primary_competency'] for x in items)!=Counter({DX:5,MK:5}):raise SystemExit('competencies')
    for x in items:
        n=x['num'];bp=x['blueprint'];it=x['item'];key=it['intended_key'];de=x['explanation']['distractor_explanations'];em={e['option']:e for e in x['evidence_map']}
        if key!=KEYS[n] or bp['official_outline_path']!=[bp['primary_system']] or bp['primary_system'] not in {ENDO,RENAL} or bp['primary_competency'] not in {DX,MK}:raise SystemExit(f'Q{n} blueprint/key')
        if any(d not in DISC for d in bp['disciplines']) or not bp['internal_content_path']:raise SystemExit(f'Q{n} discipline')
        if list(it['options'])!=list('ABCDE') or len(set(it['options'].values()))!=5 or it['difficulty']!='moderate-hard' or not it['lead_in'].endswith('?'):raise SystemExit(f'Q{n} item')
        if set(de)!=set('ABCDE') or set(em)!=set('ABCDE') or not x['explanation']['key_explanation'] or not x['explanation']['educational_objective']:raise SystemExit(f'Q{n} rationale')
        ids={s['source_id'] for s in x['sources']}
        if len(x['sources'])<3:raise SystemExit(f'Q{n} sources')
        for L in 'ABCDE':
            if em[L]['claim']!=de[L] or em[L]['direct_or_inference']!=('direct' if L==key else 'inference') or not set(em[L]['source_ids']).issubset(ids):raise SystemExit(f'Q{n} evidence {L}')
            if L!=key and ('It is not selected because it does not account for' not in de[L] or len(de[L])<160):raise SystemExit(f'Q{n} distractor {L}')
        if x['sources'][0]['agency']!='USMLE' or bp['primary_system'] not in x['sources'][0]['section_locator'] or bp['primary_competency'] not in x['sources'][0]['section_locator']:raise SystemExit(f'Q{n} locator')
        if 'ncjmm' in json.dumps(x).casefold():raise SystemExit(f'Q{n} NCJMM')
        if x['author_self_audit']['unresolved_concerns'] or x['author_self_audit']['suggested_changes']:raise SystemExit(f'Q{n} unresolved')

def anchor_scan(items):
    con=sqlite3.connect(DB.resolve().as_uri()+'?mode=ro&immutable=1',uri=True);assert con.execute('pragma integrity_check').fetchone()[0]=='ok'
    rows=con.execute("select candidate_id,payload_json from step2_final_items where final_status='FINAL_10_10_PASS'").fetchall();con.close();assert len(rows)==1280
    material=[(cid,material_text(json.loads(pj))) for cid,pj in rows]
    for x in items:
        n=x['num']
        for a in ANCHORS[n]:
            aa=a.casefold();hits=[cid for cid,text in material if has_anchor(text,aa)]
            if hits:raise SystemExit(f'Q{n} material anchor collision {a}: {hits[:5]}')

def main():
    st=json.loads(STATE.read_text())
    if st.get('final_status')!='FINAL_10_10_PASS' or st.get('item_count')!=1280 or st.get('step2_final_review_count')!=1280 or st.get('post_authoritative_db_blob')!=PRE_BLOB or st.get('contiguous_q0001_q1280') is not True:raise SystemExit('Q1280 binding')
    if gitblob(DB)!=PRE_BLOB:raise SystemExit('DB blob')
    items=build();validate(items);anchor_scan(items)
    b={'batch_id':'Q1281-Q1290-20260906-AUTHOR','production_count_before':1280,'production_count_after':1280,'status':'AUTHOR_ZERO_TRUST_PASS_PENDING_CANONICAL_DUPLICATE_AND_FINAL_QA','created_at':'2026-09-06','country_scope':'United States','specification_version':'USMLE Step 1 current official specifications verified 2026-09-06','canonical_pre_state':{'item_count':1280,'db_blob':PRE_BLOB,'state_file':'usmle/state/step2_final_q0001_q1280.json'},'batch_design':{'systems':{ENDO:5,RENAL:5},'competencies':{DX:5,MK:5},'reason':'Current USMLE-aligned deficit coverage with construct novelty selected only after material-anchor prospect screening against all 1280 canonical items.'},'answer_key_distribution':dict(sorted(Counter(x['item']['intended_key'] for x in items).items())),'answer_key_sequence':'BDACECAEDB','items':items}
    OUT.write_text(json.dumps(b,indent=2,ensure_ascii=False)+'\n')
    print(json.dumps({'status':'PASS','output':str(OUT.relative_to(REPO)),'items':10,'keys':'BDACECAEDB','canonical_blob':PRE_BLOB},sort_keys=True))
if __name__=='__main__':main()
